::before,
::after {
    --tw-content: '';
}

*,
*::before,
*::after {
    box-sizing: border-box;
    border-width: 0;
    border-style: solid;
}                    

.html__agency,
.body__agency {
  height: 100%;
  font-family: SourceSans;
  font-weight: 400;
}


.mt-20level {
  margin-top: 5rem;
}

.agency__flex-justify-end {
  display: flex;
  justify-content: flex-end;
}

.mt-20px {
  margin-top: 20px;
}

.text-info-report {
  text-align: left;
  font-size: 0.875rem;
  line-height: 1.25rem;
  line-height: 1.25;
  --tw-text-opacity: 1;
  color: rgb(31 41 55 / var(--tw-text-opacity));
}

.mt-1level {
  margin-top: 0.25rem;
}

.agency__font-semibold {
  font-weight: 600;
}

.mt-0.5level {
  margin-top: 0.125rem;
}

.agency__font-normal {
  font-weight: 400;
}

.agency__text-gray-800-hover {
  --tw-text-opacity: 1;
  color: rgb(31 41 55 / var(--tw-text-opacity));
}

.agency__text-gray-800-hover:hover {
  text-decoration-line: underline;
}

.agency__flex-justify-between {
  display: flex;
  justify-content: space-between;
}

.mt-5level {
  margin-top: 1.25rem;
}

.ml-10px {
  margin-left: 10px;
}

.w-300px {
  width: 300px;
}

.agency__text-left {
  text-align: left;
}

.agency__text-right {
  text-align: right;
}

.penawaran_inner {
  margin-left: 10px;
  padding-left: 5px;
  padding-right: 5px;
  padding-top: 3px;
  padding-bottom: 5px;
}

.penawaran_inner_table {
  margin-left: 10px;
  width: 100%;
  table-layout: auto;
  --tw-border-spacing-y: 0.5rem;
  border-spacing: var(--tw-border-spacing-x) var(--tw-border-spacing-y);
  text-align: left;
}

.agency__bg-f0f0f0 {
  --tw-bg-opacity: 1;
  background-color: rgb(240 240 240 / var(--tw-bg-opacity));
}

.title_table_penawaran {
  font-size: 0.75rem;
  line-height: 1rem;
  font-style: italic;
}

.pl-10px {
  padding-left: 10px;
}

.premi_table {
  margin-left: 10px;
  width: 100%;
  table-layout: auto;
  --tw-border-spacing-y: 0.5rem;
  border-spacing: var(--tw-border-spacing-x) var(--tw-border-spacing-y);
  text-align: left;
}

.mt-10level {
  margin-top: 2.5rem;
}

.table_coverage {
  margin-left: 10px;
  margin-top: 1.25rem;
  width: 799px;
  border-collapse: collapse;
  border-width: 1px;
  --tw-border-opacity: 1;
  border-color: rgb(229 231 235 / var(--tw-border-opacity));
  text-align: left;
}

.agency__bg-c5b8b8 {
  --tw-bg-opacity: 1;
  background-color: rgb(197 184 184 / var(--tw-bg-opacity));
}

.table_coverage_col {
  border-width: 1px;
  --tw-border-opacity: 1;
  border-color: rgb(209 213 219 / var(--tw-border-opacity));
  padding-left: 1rem;
  padding-right: 1rem;
  padding-top: 0.5rem;
  padding-bottom: 0.5rem;
  --tw-text-opacity: 1;
  color: rgb(51 51 51 / var(--tw-text-opacity));
}

.table_coverage_col_td {
  border-width: 1px;
  --tw-border-opacity: 1;
  border-color: rgb(209 213 219 / var(--tw-border-opacity));
  padding-left: 1rem;
  padding-right: 1rem;
  padding-top: 0.5rem;
  padding-bottom: 0.5rem;
}

.table_benefit {
  margin-top: 0.75rem;
  width: 799px;
  border-collapse: collapse;
  border-width: 1px;
  --tw-border-opacity: 1;
  border-color: rgb(229 231 235 / var(--tw-border-opacity));
  text-align: left;
  margin-left: 10px;
}

.ml-5level {
  margin-left: 1.25rem;
}

.agency__list-decimal {
  list-style-type: decimal;
}

.agency__list-disc {
  list-style-type: disc;
}

.mb-32level {
  margin-bottom: 8rem;
}


